var f1=field('Title', 'input', it.title), f2=field('Description','textarea', it.description), f3=field('Address (link)','input', it.url);
var row=document.createElement('div'); row.style.display='flex'; row.style.gap='8px';
var save=document.createElement('button'); save.className='btn'; save.textContent='Save changes';
var cancel=document.createElement('button'); cancel.className='btn secondary'; cancel.textContent='Cancel';
save.onclick=function(){
  it.title=f1.querySelector('input').value.trim()||it.title;
  it.description=f2.querySelector('textarea').value.trim();
  var newUrl=f3.querySelector('input').value.trim();
  if(newUrl){ it.url=normalizeUrl(newUrl); it.host=hostOf(newUrl); it.iconLetter=it.host.charAt(0).toUpperCase(); it.color=colorFor(it.host); }
  it._editing=false; render();
};
cancel.onclick=function(){ it._editing=false; render(); };
row.appendChild(save); row.appendChild(cancel);
body.appendChild(f1); body.appendChild(f2); body.appendChild(f3); body.appendChild(row);

