function esc(s){ return s.replace(/[&<>]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]; }); }
var highlights = [];
function hl(text){ var t=esc(text||''); if(!highlights.length) return t;
  var parts=highlights.filter(Boolean).map(function(h){ return h.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); });
  if(!parts.length) return t;
  var rx=new RegExp('('+parts.join('|')+')','ig');
  return t.replace(rx,'<mark>$1</mark>');
}
// text of an entry that search looks through (notes/tags included once they exist)
function textOf(it){ return (it.title+' '+it.description+' '+it.url+' '+(it.notes||'')+' '+((it.tags||[]).join(' '))).toLowerCase(); }

// --- query language: "phrases", AND / OR / NOT, ( ), #tag; operators only when unquoted ---
function tokenize(s){ var out=[], i=0, n=s.length;
  while(i<n){ var c=s[i];
    if(/\s/.test(c)){ i++; continue; }
    if(c==='('){ out.push({t:'LP'}); i++; continue; }
    if(c===')'){ out.push({t:'RP'}); i++; continue; }
