function tagEditor(tags){
  var current=(tags||[]).slice();
  var w=document.createElement('div'); w.className='field';
  var l=document.createElement('label'); l.textContent='Tags';
  var box=document.createElement('div'); box.className='tagbox';
  var inp=document.createElement('input'); inp.type='text'; inp.placeholder='Add a tag, press Enter';
  function draw(){
    Array.prototype.slice.call(box.querySelectorAll('.chip')).forEach(function(c){ c.remove(); });
    current.forEach(function(t){
      var chip=document.createElement('span'); chip.className='chip'; chip.appendChild(document.createTextNode(t));
      var x=document.createElement('button'); x.type='button'; x.className='chipx'; x.textContent='×';
      x.onclick=function(){ current=current.filter(function(y){return y!==t;}); draw(); };
      chip.appendChild(x); box.insertBefore(chip, inp);
    });
  }
  function addTag(raw){ var t=normTag(raw); if(t && current.indexOf(t)===-1) current.push(t); inp.value=''; draw(); }
  inp.addEventListener('keydown', function(e){
    if(e.key==='Enter'||e.key===','){ e.preventDefault(); addTag(inp.value); }
    else if(e.key==='Backspace' && inp.value==='' && current.length){ current.pop(); draw(); }
  });
  box.appendChild(inp); draw();
  w.appendChild(l); w.appendChild(box);
  w.getTags=function(){ if(inp.value.trim()) addTag(inp.value); return current.slice(); };
  return w;
}

