function applySaved(s){ query=s.query; document.getElementById('searchInput').value=s.query; clearSelection(); render(); }
function renderSaved(){
  var bar=document.getElementById('savedbar'); bar.innerHTML='';
  if(savingSearch){
    bar.style.display='flex';
    var q=query.trim();
    var wrap=document.createElement('div'); wrap.className='saveform';
    var lab=document.createElement('span'); lab.className='slabel'; lab.textContent='Save current search:';
    var nm=document.createElement('input'); nm.placeholder='Name this search'; nm.value=q;
    var sv=document.createElement('button'); sv.className='savebtn'; sv.textContent='Save';
    var cn=document.createElement('button'); cn.className='savebtn'; cn.textContent='Cancel';
    var qd=document.createElement('span'); qd.className='slabel'; qd.textContent='— finds: '+q;
    function doSave(){ var name=nm.value.trim()||q; savedSearches.push({id:Date.now(), name:name, query:q}); savingSearch=false; renderSaved(); }
    sv.onclick=doSave; cn.onclick=function(){ savingSearch=false; renderSaved(); };
    nm.addEventListener('keydown',function(e){ if(e.key==='Enter'){ e.preventDefault(); doSave(); } });
    wrap.appendChild(lab); wrap.appendChild(nm); wrap.appendChild(sv); wrap.appendChild(cn); wrap.appendChild(qd);
    bar.appendChild(wrap); setTimeout(function(){ nm.focus(); nm.select(); },0); return;
  }
  if(!savedSearches.length){ bar.style.display='none'; return; }
  bar.style.display='flex';
  var slbl=document.createElement('span'); slbl.className='slabel'; slbl.textContent='Saved searches:'; bar.appendChild(slbl);
  savedSearches.forEach(function(s){
    var chip=document.createElement('span'); chip.className='schip'; chip.appendChild(document.createTextNode(s.name)); chip.title=s.query;
    chip.onclick=function(){ applySaved(s); };
    var x=document.createElement('button'); x.className='sx'; x.textContent='×'; x.title='Delete saved search';
    x.onclick=function(e){ e.stopPropagation(); savedSearches=savedSearches.filter(function(y){return y!==s;}); renderSaved(); };
    chip.appendChild(x); bar.appendChild(chip);
  });
}

function render(){
  renderSaved();
  var list=document.getElementById('list'), count=document.getElementById('count');

