function buildSettings(){
  var s=document.getElementById('settings'); s.innerHTML='';
  if(!settingsOpen){ s.style.display='none'; return; }
  s.style.display='block';
  var h=document.createElement('div'); h.className='settings-title'; h.textContent='Display settings'; s.appendChild(h);
  // default sort
  var ds=document.createElement('select');
  SORT_OPTIONS.forEach(function(o){ var op=document.createElement('option'); op.value=o[0]; op.textContent=o[1]; if(o[0]===prefs.defaultSort) op.selected=true; ds.appendChild(op); });
  ds.onchange=function(){ prefs.defaultSort=ds.value; sortMode=ds.value; document.getElementById('sortSelect').value=ds.value; pageChunks=1; render(); };
  s.appendChild(prefRow('Default sort (used when the app opens)', ds));
  // items per page
  var ps=document.createElement('select');
  [['5','5'],['10','10'],['25','25'],['50','50'],['all','All']].forEach(function(o){ var op=document.createElement('option'); op.value=o[0]; op.textContent=o[1]; var cur=(prefs.pageSize===Infinity?'all':String(prefs.pageSize)); if(o[0]===cur) op.selected=true; ps.appendChild(op); });
  ps.onchange=function(){ prefs.pageSize = ps.value==='all'?Infinity:parseInt(ps.value,10); pageChunks=1; render(); };
  s.appendChild(prefRow('Items shown per page', ps));
  // text size
  var tsz=document.createElement('select');
  [['sm','Small'],['md','Medium'],['lg','Large']].forEach(function(o){ var op=document.createElement('option'); op.value=o[0]; op.textContent=o[1]; if(o[0]===prefs.textSize) op.selected=true; tsz.appendChild(op); });
  tsz.onchange=function(){ prefs.textSize=tsz.value; applyTextSize(); render(); };
  s.appendChild(prefRow('Text size', tsz));
  var done=document.createElement('button'); done.className='hbtn'; done.style.marginTop='12px'; done.textContent='Done'; done.onclick=function(){ settingsOpen=false; buildSettings(); };
  s.appendChild(done);
}

