:root { --bg:#f6f7f9; --card:#fff; --line:#e4e7eb; --text:#1c2430; --muted:#6b7684; --accent:#2f6fed; --warn:#b46a00; --danger:#c0392b; }
* { box-sizing:border-box; }
body { margin:0; font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif; background:var(--bg); color:var(--text); }
header { background:var(--card); border-bottom:1px solid var(--line); padding:18px 20px; display:flex; justify-content:space-between; align-items:center; gap:12px; flex-wrap:wrap; }
header h1 { margin:0; font-size:20px; }
header p { margin:4px 0 0; color:var(--muted); font-size:13px; }
.headctrls { display:flex; gap:8px; }
.hbtn { font-size:13px; padding:8px 12px; border:1px solid var(--line); border-radius:8px; background:var(--card); color:var(--text); cursor:pointer; }
.iomsg { max-width:760px; margin:0 auto; padding:10px 20px 0; }
.iomsg .inner { background:#eaf5ec; border:1px solid #bfe0c6; color:#1f6b3b; border-radius:8px; padding:9px 12px; font-size:13px; }
main { max-width:760px; margin:0 auto; padding:20px; }

.save { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; display:flex; gap:10px; }
.save input { flex:1; padding:11px 12px; border:1px solid var(--line); border-radius:8px; font-size:15px; }
.btn { padding:11px 18px; border:0; border-radius:8px; background:var(--accent); color:#fff; font-size:15px; cursor:pointer; }
.btn.secondary { background:#eef0f3; color:var(--text); }
.btn.danger { background:var(--danger); color:#fff; }
.btn:disabled { opacity:.5; cursor:default; }
.notice { color:var(--warn); font-size:13px; margin:10px 4px 0; }

.field { display:flex; flex-direction:column; gap:5px; margin-bottom:12px; }
.field label { font-size:12px; color:var(--muted); font-weight:600; }
.field input, .field textarea { padding:9px 11px; border:1px solid var(--line); border-radius:8px; font-size:14px; font-family:inherit; }
.field textarea { resize:vertical; min-height:52px; }
.card { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; margin-top:12px; }
.compose-head { font-size:13px; color:var(--muted); margin-bottom:10px; }
.compose-head.failed { color:var(--warn); }
.preview { display:flex; gap:14px; }
.thumb { width:120px; height:80px; border-radius:8px; flex:0 0 auto; background-size:cover; background-position:center; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:700; font-size:12px; text-align:center; overflow:hidden; }

.choice { display:inline-flex; gap:6px; }
.choice button { border:1px solid var(--line); background:var(--card); border-radius:8px; padding:7px 12px; font-size:13px; cursor:pointer; color:var(--text); }
.choice button.on { border-color:var(--accent); background:#eef3ff; color:var(--accent); font-weight:600; }

.tagbox { display:flex; flex-wrap:wrap; gap:6px; align-items:center; border:1px solid var(--line); border-radius:8px; padding:6px 8px; }
.tagbox input { border:0; outline:none; flex:1; min-width:140px; font-size:14px; padding:4px; }
.chip { display:inline-flex; align-items:center; gap:5px; background:#eef3ff; color:#274690; border-radius:999px; padding:3px 5px 3px 10px; font-size:12px; }
.chip .chipx { border:0; background:none; color:#274690; cursor:pointer; font-size:14px; line-height:1; padding:0 2px; }
.suggest { display:flex; flex-wrap:wrap; gap:6px; margin-top:6px; }
.suggest .sughint { font-size:11px; color:var(--muted); align-self:center; }
.suggest .sugtag { background:#fff; border:1px solid var(--line); color:#274690; border-radius:999px; padding:3px 10px; font-size:12px; cursor:pointer; }

.toolbar { display:flex; justify-content:space-between; align-items:center; gap:12px; margin-top:16px; }
.linkbtn2 { font-size:13px; padding:6px 10px; border:1px solid var(--line); border-radius:8px; background:var(--card); color:var(--accent); cursor:pointer; }
.sortlabel { font-size:13px; color:var(--muted); display:inline-flex; gap:6px; align-items:center; }
.sortlabel select { font-size:13px; padding:6px 8px; border:1px solid var(--line); border-radius:8px; background:var(--card); color:var(--text); }

.savedbar { display:flex; flex-wrap:wrap; gap:8px; margin-top:10px; align-items:center; }
.savedbar .slabel { font-size:12px; color:var(--muted); }
.savedbar .schip { display:inline-flex; align-items:center; gap:4px; background:#eef3ff; color:#274690; border:1px solid #d7e2fb; border-radius:999px; padding:4px 6px 4px 12px; font-size:13px; cursor:pointer; }
.savedbar .schip .sx { border:0; background:none; color:#274690; cursor:pointer; font-size:14px; padding:0 2px; }
.saveform { display:flex; gap:8px; align-items:center; flex-wrap:wrap; }
.saveform input { padding:8px 10px; border:1px solid var(--line); border-radius:8px; font-size:13px; min-width:200px; }
.saveform .err { color:var(--warn); font-size:12px; width:100%; }

.searchwrap { margin-top:16px; }
.searchwrap input { width:100%; padding:11px 14px; border:1px solid var(--line); border-radius:10px; font-size:15px; background:var(--card); }
mark { background:#fff2b0; color:inherit; padding:0 1px; border-radius:2px; }

.segmented { display:inline-flex; border:1px solid var(--line); border-radius:10px; overflow:hidden; margin-top:16px; background:var(--card); }
.segmented button { border:0; background:transparent; padding:9px 16px; font-size:14px; cursor:pointer; color:var(--muted); border-right:1px solid var(--line); }
.segmented button:last-child { border-right:0; }
.segmented button.active { background:var(--accent); color:#fff; }

.count { color:var(--muted); font-size:13px; margin:20px 4px 8px; }

.bulkbar { position:sticky; top:0; z-index:5; background:#1c2430; color:#fff; border-radius:10px; padding:10px 12px; margin-bottom:12px; display:flex; gap:8px; align-items:center; flex-wrap:wrap; }
.bulkbar .bcount { font-weight:600; font-size:14px; margin-right:4px; }
.bulkbar .scopehint { font-size:12px; color:#c7cdd6; width:100%; margin-top:2px; }
.bulkbar button { border:0; border-radius:7px; padding:7px 11px; font-size:13px; cursor:pointer; background:#333d4c; color:#fff; }
.bulkbar button.primary { background:var(--accent); }
.bulkbar button.danger { background:var(--danger); }
.bulkbar button.ghost { background:transparent; color:#c7cdd6; text-decoration:underline; padding:7px 4px; }
.bulkbar input.btag { border:0; border-radius:7px; padding:7px 10px; font-size:13px; min-width:150px; }

ul.list { list-style:none; margin:0; padding:0; display:flex; flex-direction:column; gap:12px; }
li.item { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; }
li.item.selected { border-color:var(--accent); box-shadow:0 0 0 1px var(--accent) inset; }
.item-top { display:flex; gap:14px; }
.selbox { width:17px; height:17px; margin-top:2px; flex:0 0 auto; cursor:pointer; }
.item-body { flex:1; min-width:0; }
.titlerow { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.icon { width:20px; height:20px; border-radius:5px; flex:0 0 auto; display:inline-flex; align-items:center; justify-content:center; color:#fff; font-weight:700; font-size:11px; }
.item a.title { font-size:15px; font-weight:600; color:var(--text); text-decoration:none; overflow-wrap:anywhere; }
.item a.title:hover { color:var(--accent); text-decoration:underline; }
.badge { display:inline-block; font-size:11px; font-weight:600; padding:2px 8px; border-radius:999px; }
.badge.toread { background:#fdeccd; color:#8a5a00; }
.badge.archived { background:#dfe9ff; color:#274690; }
.badge.offline { background:#e2f0e5; color:#1f6b3b; }
.item .desc { color:#43505f; font-size:13px; margin-top:5px; overflow-wrap:anywhere; }
.item .desc.clamped { display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden; }
.tags { display:flex; flex-wrap:wrap; gap:6px; margin-top:8px; }
.tags .tag { background:#eef3ff; color:#274690; border:0; border-radius:999px; padding:3px 10px; font-size:12px; cursor:pointer; }
.item .note { margin-top:8px; padding:8px 11px; background:#fbfaf4; border-left:3px solid #d9c98a; border-radius:6px; font-size:13px; color:#4a4636; }
.item .note.collapsed { max-height:6.5em; overflow:hidden; }
.item .note h3,.item .note h4 { margin:4px 0; font-size:14px; }
.item .note p { margin:4px 0; }
.item .note ul,.item .note ol { margin:4px 0 4px 20px; padding:0; }
